1	import { Wheat, ChefHat, Receipt, FileEdit, Layers } from 'lucide-react';
2	
3	interface NodePaletteProps {
4	  hasFocus: boolean;
5	  onAddInsumo: () => void;
6	  onAddSubReceita: () => void;
7	  onAddNF: () => void;
8	  onAddEsboco: () => void;
9	  onAddFicha: () => void;
10	}
11	
12	interface PaletteButtonProps {
13	  icon: React.ReactNode;
14	  label: string;
15	  shape: 'round' | 'rect';
16	  color: 'violet' | 'amber' | 'blue' | 'orange' | 'emerald';
17	  onClick: () => void;
18	  disabled?: boolean;
19	  disabledTitle?: string;
20	}
21	
22	const COLOR_CLASSES: Record<PaletteButtonProps['color'], { bg: string; border: string; text: string; hover: string }> = {
23	  violet:  { bg: 'bg-violet-50 dark:bg-violet-950/40',  border: 'border-violet-300 dark:border-violet-700',  text: 'text-violet-600 dark:text-violet-400',  hover: 'hover:border-violet-500 hover:bg-violet-100 dark:hover:bg-violet-900/50' },
24	  amber:   { bg: 'bg-amber-50 dark:bg-amber-950/40',     border: 'border-amber-300 dark:border-amber-700',    text: 'text-amber-600 dark:text-amber-400',    hover: 'hover:border-amber-500 hover:bg-amber-100 dark:hover:bg-amber-900/50' },
25	  blue:    { bg: 'bg-blue-50 dark:bg-blue-950/40',       border: 'border-blue-300 dark:border-blue-700',      text: 'text-blue-600 dark:text-blue-400',      hover: 'hover:border-blue-500 hover:bg-blue-100 dark:hover:bg-blue-900/50' },
26	  orange:  { bg: 'bg-orange-50 dark:bg-orange-950/40',   border: 'border-orange-300 dark:border-orange-700',  text: 'text-orange-600 dark:text-orange-400',  hover: 'hover:border-orange-500 hover:bg-orange-100 dark:hover:bg-orange-900/50' },
27	  emerald: { bg: 'bg-emerald-50 dark:bg-emerald-950/40', border: 'border-emerald-300 dark:border-emerald-700',text: 'text-emerald-600 dark:text-emerald-400',hover: 'hover:border-emerald-500 hover:bg-emerald-100 dark:hover:bg-emerald-900/50' },
28	};
29	
30	function PaletteButton({
31	  icon, label, shape, color, onClick, disabled, disabledTitle,
32	}: PaletteButtonProps) {
33	  const c = COLOR_CLASSES[color];
34	  return (
35	    <button
36	      onClick={onClick}
37	      disabled={disabled}
38	      title={disabled && disabledTitle ? disabledTitle : label}
39	      className={`group relative flex flex-col items-center gap-1 px-2 py-2 ${
40	        shape === 'round' ? 'rounded-full' : 'rounded-lg'
41	      } border-2 ${c.bg} ${c.border} ${c.text} ${
42	        disabled
43	          ? 'opacity-40 cursor-not-allowed'
44	          : `${c.hover} hover:scale-105 hover:shadow-md transition-all duration-150 active:scale-95`
45	      }`}
46	    >
47	      <div className="h-4 w-4 flex items-center justify-center">{icon}</div>
48	      <span className="text-[8px] font-bold uppercase tracking-wide leading-none">
49	        {label}
50	      </span>
51	    </button>
52	  );
53	}
54	
55	/**
56	 * Paleta lateral de nodes (estilo n8n).
57	 * Fixa no canto esquerdo. Botões pra adicionar cada tipo de node.
58	 */
59	export function NodePalette({
60	  hasFocus,
61	  onAddInsumo,
62	  onAddSubReceita,
63	  onAddNF,
64	  onAddEsboco,
65	  onAddFicha,
66	}: NodePaletteProps) {
67	  return (
68	    <div className="absolute top-20 left-3 z-20 flex flex-col gap-1.5 rounded-2xl bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-border shadow-xl p-2 animate-in fade-in slide-in-from-left-4 duration-300">
69	      <div className="text-[8px] font-bold uppercase tracking-wider text-muted-foreground text-center pb-1 border-b border-border">
70	        Nodes
71	      </div>
72	
73	      <PaletteButton
74	        icon={<ChefHat className="h-4 w-4" />}
75	        label="Ficha"
76	        shape="rect"
77	        color="emerald"
78	        onClick={onAddFicha}
79	      />
80	      <PaletteButton
81	        icon={<Wheat className="h-4 w-4" />}
82	        label="Insumo"
83	        shape="rect"
84	        color="violet"
85	        onClick={onAddInsumo}
86	      />
87	      <PaletteButton
88	        icon={<ChefHat className="h-4 w-4" />}
89	        label="Sub-rec."
90	        shape="rect"
91	        color="amber"
92	        onClick={onAddSubReceita}
93	        disabled={!hasFocus}
94	        disabledTitle="Foque numa ficha primeiro"
95	      />
96	      <PaletteButton
97	        icon={<Receipt className="h-4 w-4" />}
98	        label="NF"
99	        shape="round"
100	        color="blue"
101	        onClick={onAddNF}
102	      />
103	      <PaletteButton
104	        icon={<FileEdit className="h-4 w-4" />}
105	        label="Esboço"
106	        shape="rect"
107	        color="orange"
108	        onClick={onAddEsboco}
109	        disabled={!hasFocus}
110	        disabledTitle="Foque numa ficha primeiro"
111	      />
112	
113	      <div className="mt-1 pt-1 border-t border-border flex items-center justify-center">
114	        <Layers className="h-3 w-3 text-muted-foreground opacity-50" />
115	      </div>
116	    </div>
117	  );
118	}
