1	import { useEffect, useMemo, useState } from 'react';
2	import { X, Search, Wheat, ChefHat, Plus, Sparkles, BookOpen, FileEdit, Loader2 } from 'lucide-react';
3	import { Input } from '@/shared/ui/input';
4	import { Button } from '@/shared/ui/button';
5	import { Label } from '@/shared/ui/label';
6	import {
7	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
8	} from '@/shared/ui/select';
9	import { supabase } from '@/integrations/supabase/client';
10	import { toast } from 'sonner';
11	import type { RawFicha, RawInsumo } from '@/hooks/producao/useRecipeGraph';
12	
13	const fmtBRL = (n: number) =>
14	  n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
15	
16	const UNIDADES = ['g', 'kg', 'mL', 'L', 'un'] as const;
17	
18	type Tab = 'insumo' | 'sub_receita' | 'esboco';
19	
20	export interface PickInsumoPayload {
21	  tipo: 'insumo';
22	  insumoId: number;
23	  insumoNome: string;
24	}
25	
26	export interface PickSubReceitaPayload {
27	  tipo: 'sub_receita';
28	  subFichaId: number;
29	  subFichaNome: string;
30	}
31	
32	interface AddIngredientPanelProps {
33	  open: boolean;
34	  onClose: () => void;
35	  fichaTargetId: number;
36	  fichaTargetNome: string;
37	  insumos: RawInsumo[];
38	  fichas: RawFicha[];
39	  onPickInsumo: (payload: PickInsumoPayload) => void;
40	  onPickSubReceita: (payload: PickSubReceitaPayload) => void;
41	  onCreateNovoInsumo: () => void;
42	  onSaved: () => void;
43	  initialTab?: 'insumo' | 'sub_receita' | 'esboco';
44	}
45	
46	export function AddIngredientPanel({
47	  open,
48	  onClose,
49	  fichaTargetId,
50	  fichaTargetNome,
51	  insumos,
52	  fichas,
53	  onPickInsumo,
54	  onPickSubReceita,
55	  onCreateNovoInsumo,
56	  onSaved,
57	  initialTab,
58	}: AddIngredientPanelProps) {
59	  const [tab, setTab] = useState<Tab>(initialTab ?? 'insumo');
60	  const [query, setQuery] = useState('');
61	
62	  // Esboço (texto)
63	  const [esbocoNome, setEsbocoNome] = useState('');
64	  const [esbocoTipo, setEsbocoTipo] = useState<'insumo' | 'sub_receita'>('insumo');
65	  const [esbocoQtd, setEsbocoQtd] = useState<number>(0);
66	  const [esbocoUnidade, setEsbocoUnidade] = useState<string>('g');
67	  const [esbocoPreco, setEsbocoPreco] = useState<number>(0);
68	  const [savingEsboco, setSavingEsboco] = useState(false);
69	
70	  useEffect(() => {
71	    if (open) {
72	      setTab(initialTab ?? 'insumo');
73	    } else {
74	      setQuery('');
75	      setTab('insumo');
76	      setEsbocoNome('');
77	      setEsbocoTipo('insumo');
78	      setEsbocoQtd(0);
79	      setEsbocoUnidade('g');
80	      setEsbocoPreco(0);
81	    }
82	  }, [open, initialTab]);
83	
84	  useEffect(() => {
85	    if (!open) return;
86	    const handler = (e: KeyboardEvent) => {
87	      if (e.key === 'Escape') onClose();
88	    };
89	    window.addEventListener('keydown', handler);
90	    return () => window.removeEventListener('keydown', handler);
91	  }, [open, onClose]);
92	
93	  const filteredInsumos = useMemo(() => {
94	    const q = query.trim().toLowerCase();
95	    if (!q) return insumos.slice(0, 50);
96	    return insumos.filter((i) => i.nome.toLowerCase().includes(q)).slice(0, 50);
97	  }, [insumos, query]);
98	
99	  const filteredFichas = useMemo(() => {
100	    const q = query.trim().toLowerCase();
101	    const others = fichas.filter((f) => f.id !== fichaTargetId);
102	    if (!q) return others.slice(0, 50);
103	    return others.filter((f) => f.nome.toLowerCase().includes(q)).slice(0, 50);
104	  }, [fichas, query, fichaTargetId]);
105	
106	  const handleSalvarEsboco = async () => {
107	    if (!esbocoNome.trim() || esbocoQtd <= 0) {
108	      toast.error('Preencha nome e quantidade');
109	      return;
110	    }
111	    setSavingEsboco(true);
112	    try {
113	      const { error } = await supabase.from('ficha_tecnica_itens').insert({
114	        ficha_tecnica_id: fichaTargetId,
115	        tipo: esbocoTipo,
116	        observacao: esbocoNome.trim(),
117	        quantidade: esbocoQtd,
118	        unidade: esbocoUnidade,
119	        preco_unitario_esboco: esbocoPreco > 0 ? esbocoPreco : null,
120	        ordem: 0,
