1	import { useState } from 'react';
2	import { useReactFlow } from '@xyflow/react';
3	import {
4	  ZoomIn,
5	  ZoomOut,
6	  Maximize2,
7	  Lock,
8	  Unlock,
9	  Crosshair,
10	  RotateCcw,
11	  LayoutGrid,
12	} from 'lucide-react';
13	import { layoutGraph } from '@/components/producao/configurador/layout';
14	import { toast } from 'sonner';
15	
16	interface ToolbarButtonProps {
17	  onClick: () => void;
18	  title: string;
19	  active?: boolean;
20	  children: React.ReactNode;
21	}
22	
23	function ToolbarButton({ onClick, title, active, children }: ToolbarButtonProps) {
24	  return (
25	    <button
26	      onClick={onClick}
27	      title={title}
28	      className={`flex h-9 w-9 items-center justify-center rounded-lg transition-all duration-150 ${
29	        active
30	          ? 'bg-amber-500 text-white shadow-md hover:bg-amber-600'
31	          : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white'
32	      }`}
33	    >
34	      {children}
35	    </button>
36	  );
37	}
38	
39	interface BottomToolbarProps {
40	  onSavePosition?: (nodeId: string, x: number, y: number) => Promise<void> | void;
41	}
42	
43	export function BottomToolbar({ onSavePosition }: BottomToolbarProps = {}) {
44	  const { zoomIn, zoomOut, fitView, setCenter, setNodes, getNodes, getEdges } = useReactFlow();
45	  const [locked, setLocked] = useState(false);
46	  const [organizando, setOrganizando] = useState(false);
47	
48	  const handleLock = () => {
49	    const next = !locked;
50	    setLocked(next);
51	    setNodes((nds) => nds.map((n) => ({ ...n, draggable: !next })));
52	  };
53	
54	  const handleCenter = () => {
55	    setCenter(0, 0, { zoom: 1, duration: 600 });
56	  };
57	
58	  const handleFit = () => {
59	    fitView({ duration: 600, padding: 0.2 });
60	  };
61	
62	  const handleOrganizar = async () => {
63	    setOrganizando(true);
64	    try {
65	      const allNodes = getNodes();
66	      const visibleNodes = allNodes.filter((n) => !n.hidden);
67	      const visibleIds = new Set(visibleNodes.map((n) => n.id));
68	      const visibleEdges = getEdges().filter(
69	        (e) => visibleIds.has(e.source) && visibleIds.has(e.target)
70	      );
71	      // Re-layout só os visíveis
72	      const laidOut = layoutGraph(visibleNodes, visibleEdges, 'LR');
73	      const positionById = new Map(laidOut.map((n) => [n.id, n.position]));
74	      // Aplica visualmente
75	      setNodes((nds) =>
76	        nds.map((n) =>
77	          positionById.has(n.id)
78	            ? { ...n, position: positionById.get(n.id)! }
79	            : n
80	        )
81	      );
82	      // Persiste cada um
83	      if (onSavePosition) {
84	        await Promise.all(
85	          laidOut.map((n) => onSavePosition(n.id, n.position.x, n.position.y))
86	        );
87	      }
88	      // Fit-view depois do re-arranjo
89	      setTimeout(() => {
90	        fitView({
91	          nodes: laidOut.map((n) => ({ id: n.id })),
92	          duration: 600,
93	          padding: 0.25,
94	          maxZoom: 1.3,
95	        });
96	      }, 200);
97	      toast.success(`${laidOut.length} nodes organizados`);
98	    } catch (err) {
99	      toast.error(err instanceof Error ? err.message : 'Erro ao organizar');
100	    } finally {
101	      setOrganizando(false);
102	    }
103	  };
104	
105	  return (
106	    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-1 rounded-2xl bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-border shadow-2xl px-2 py-1.5 animate-in fade-in slide-in-from-bottom-4 duration-300">
107	      <ToolbarButton onClick={() => zoomIn({ duration: 250 })} title="Zoom +">
108	        <ZoomIn className="h-4 w-4" />
109	      </ToolbarButton>
110	      <ToolbarButton onClick={() => zoomOut({ duration: 250 })} title="Zoom −">
111	        <ZoomOut className="h-4 w-4" />
112	      </ToolbarButton>
113	
114	      <div className="mx-1 h-6 w-px bg-border" />
115	
116	      <ToolbarButton onClick={handleFit} title="Ajustar à tela">
117	        <Maximize2 className="h-4 w-4" />
118	      </ToolbarButton>
119	      <ToolbarButton onClick={handleCenter} title="Centralizar">
120	        <Crosshair className="h-4 w-4" />
121	      </ToolbarButton>
122	      <ToolbarButton
123	        onClick={handleOrganizar}
124	        title="Organizar nodes (auto-layout)"
125	        active={organizando}
126	      >
127	        <LayoutGrid className="h-4 w-4" />
128	      </ToolbarButton>
129	
130	      <div className="mx-1 h-6 w-px bg-border" />
131	
132	      <ToolbarButton
133	        onClick={handleLock}
134	        title={locked ? 'Destravar nodes' : 'Travar nodes'}
135	        active={locked}
136	      >
137	        {locked ? <Lock className="h-4 w-4" /> : <Unlock className="h-4 w-4" />}
138	      </ToolbarButton>
139	      <ToolbarButton
140	        onClick={() => fitView({ duration: 0, padding: 0.2 })}
141	        title="Reset view"
142	      >
143	        <RotateCcw className="h-4 w-4" />
144	      </ToolbarButton>
145	    </div>
146	  );
147	}
