1	import dagre from 'dagre';
2	import type { Node, Edge } from '@xyflow/react';
3	
4	const SIZES: Record<string, { w: number; h: number }> = {
5	  ficha: { w: 280, h: 130 },
6	  insumo: { w: 220, h: 90 },
7	  loose: { w: 200, h: 80 },
8	  nf: { w: 160, h: 50 },     // NF é "acessório" — pequeno
9	  produto: { w: 200, h: 80 },
10	};
11	
12	const DEFAULT = { w: 200, h: 80 };
13	
14	const sizeFor = (n: Node) => {
15	  const kind = (n.data as { kind?: string })?.kind ?? '';
16	  return SIZES[kind] ?? DEFAULT;
17	};
18	
19	export function layoutGraph(
20	  nodes: Node[],
21	  edges: Edge[],
22	  direction: 'LR' | 'TB' = 'LR'
23	): Node[] {
24	  const g = new dagre.graphlib.Graph();
25	  g.setGraph({ rankdir: direction, nodesep: 35, ranksep: 130, marginx: 60, marginy: 60 });
26	  g.setDefaultEdgeLabel(() => ({}));
27	
28	  nodes.forEach((n) => {
29	    const { w, h } = sizeFor(n);
30	    g.setNode(n.id, { width: w, height: h });
31	  });
32	  edges.forEach((e) => g.setEdge(e.source, e.target));
33	
34	  dagre.layout(g);
35	
36	  return nodes.map((n) => {
37	    const p = g.node(n.id);
38	    if (!p) return n;
39	    const { w, h } = sizeFor(n);
40	    return { ...n, position: { x: p.x - w / 2, y: p.y - h / 2 } };
41	  });
42	}
